+@page "/enroll"
+@inject CourseCatalogService CatalogService
+
+<PageTitle>Enrollment Request</PageTitle>
+
+<h1>Enrollment Request</h1>
+<p>Submit your enrollment request using the form below. You will receive confirmation via your university email.</p>
+
+@if (Submitted)
+{
+    <div class="alert alert-success">
+        <h4 class="alert-heading">Request Submitted!</h4>
+        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
+            <strong>@(CatalogService.GetCourseById(Model.CourseId)?.Title ?? "the selected course")</strong>
+            has been received.</p>
+        <hr />
+        <p class="mb-0">You will receive a confirmation email at your university address shortly.</p>
+    </div>
+    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
+}
+else
+{
+    <div class="row">
+        <div class="col-md-8 col-lg-6">
+            <form method="post">
+                <AntiforgeryToken />
+
+                <div class="mb-3">
+                    <label for="studentName" class="form-label">Full Name</label>
+                    <input type="text" class="form-control" id="studentName" name="Model.StudentName"
+                           value="@Model.StudentName" required />
+                    @if (validationErrors.ContainsKey(nameof(Model.StudentName)))
+                    {
+                        <div class="text-danger">@validationErrors[nameof(Model.StudentName)]</div>
+                    }
+                </div>
+
+                <div class="mb-3">
+                    <label for="studentId" class="form-label">Student ID</label>
+                    <input type="text" class="form-control" id="studentId" name="Model.StudentId"
+                           value="@Model.StudentId" required placeholder="e.g., STU-12345" />
+                    @if (validationErrors.ContainsKey(nameof(Model.StudentId)))
+                    {
+                        <div class="text-danger">@validationErrors[nameof(Model.StudentId)]</div>
+                    }
+                </div>
+
+                <div class="mb-3">
+                    <label for="courseId" class="form-label">Course</label>
+                    <select class="form-select" id="courseId" name="Model.CourseId" required>
+                        <option value="0">-- Select a course --</option>
+                        @foreach (var course in CatalogService.GetAllCourses())
+                        {
+                            <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
+                                @course.CourseCode - @course.Title
+                            </option>
+                        }
+                    </select>
+                    @if (validationErrors.ContainsKey(nameof(Model.CourseId)))
+                    {
+                        <div class="text-danger">@validationErrors[nameof(Model.CourseId)]</div>
+                    }
+                </div>
+
+                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
+                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
+            </form>
+        </div>
+    </div>
+}
+
+@code {
